#if !defined(BINARY_SEARCH_TREE_H)
#define BINARY_SEARCH_TREE_H

#include <cstddef>
#include <iterator>
#include <memory>
#include <stack>

namespace binary_search_tree {

template <typename T>
class binary_tree;

// A forward iterator that walks a binary tree in order (left, node, right).
// It keeps the path to the current node on a stack, so incrementing an
// iterator is O(1) amortized and no extra container is needed.
template <typename T>
class tree_iterator {
public:
    using iterator_category = std::forward_iterator_tag;
    using value_type = T;
    using difference_type = std::ptrdiff_t;
    using pointer = const T*;
    using reference = const T&;

    tree_iterator() = default;

    explicit tree_iterator(const binary_tree<T>* node) { push_left(node); }

    reference operator*() const { return stack_.top()->data(); }
    pointer operator->() const { return &stack_.top()->data(); }

    tree_iterator& operator++() {
        const binary_tree<T>* node = stack_.top()->right().get();
        stack_.pop();
        push_left(node);
        return *this;
    }

    tree_iterator operator++(int) {
        tree_iterator copy(*this);
        ++(*this);
        return copy;
    }

    bool operator==(const tree_iterator& other) const {
        if (stack_.empty() != other.stack_.empty()) {
            return false;
        }
        if (stack_.empty()) {
            return true;
        }
        return stack_.top() == other.stack_.top();
    }

    bool operator!=(const tree_iterator& other) const { return !(*this == other); }

private:
    std::stack<const binary_tree<T>*> stack_;

    void push_left(const binary_tree<T>* node) {
        while (node != nullptr) {
            stack_.push(node);
            node = node->left().get();
        }
    }
};

template <typename T>
class binary_tree {
public:
    using tree_type = binary_tree<T>;
    using pointer_type = std::unique_ptr<tree_type>;

    explicit binary_tree(const T& datum)
        : data_(datum), left_(pointer_type(nullptr)), right_(pointer_type(nullptr)) {}

    void insert(const T& datum) {
        if (datum <= data_) {
            if (left_ == nullptr) {
                left_ = pointer_type(new tree_type(datum));
            } else {
                left_->insert(datum);
            }
        } else {
            if (right_ == nullptr) {
                right_ = pointer_type(new tree_type(datum));
            } else {
                right_->insert(datum);
            }
        }
    }

    const T& data() const { return data_; }

    const pointer_type& left() const { return left_; }
    const pointer_type& right() const { return right_; }

    tree_iterator<T> begin() const { return tree_iterator<T>(this); }
    tree_iterator<T> end() const { return tree_iterator<T>(); }

private:
    T data_;
    pointer_type left_;
    pointer_type right_;
};

